package com.utterlazy.order;

import com.utterlazy.order.application.PricingCalculator;

import java.io.IOException;
import java.math.BigDecimal;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Cross-language pricing parity check.
 *
 * Reads the TSV generated by `php artisan pricing:vectors` and recomputes every
 * case with the Java calculator. Exits non-zero on any mismatch.
 *
 * Usage: java -cp out com.utterlazy.order.PricingParityCli <golden.tsv>
 */
public final class PricingParityCli {

    private static int pass = 0;
    private static int fail = 0;

    public static void main(String[] args) throws IOException {
        if (args.length < 1) {
            System.err.println("usage: PricingParityCli <golden.tsv>");
            System.exit(2);
        }

        List<String> lines = Files.readAllLines(Path.of(args[0])).stream()
                .filter(l -> !l.isBlank())
                .toList();

        if (lines.size() < 2) {
            System.err.println("golden file is empty");
            System.exit(2);
        }

        String[] header = lines.get(0).split("\t", -1);
        Map<String, Integer> idx = new HashMap<>();
        for (int i = 0; i < header.length; i++) {
            idx.put(header[i].trim(), i);
        }

        PricingCalculator calculator = new PricingCalculator();

        for (String line : lines.subList(1, lines.size())) {
            String[] parts = line.split("\t", -1);
            String id = parts[idx.get("id")];

            PricingCalculator.Input input = new PricingCalculator.Input(
                    bd(parts, idx, "subtotal"),
                    bd(parts, idx, "vendor_discount_rate"),
                    bd(parts, idx, "tax_rate"),
                    bd(parts, idx, "delivery_min"),
                    bd(parts, idx, "delivery_max"),
                    bd(parts, idx, "delivery_estimate"),
                    bd(parts, idx, "delivery_free_above"),
                    bd(parts, idx, "platform_fee"),
                    bd(parts, idx, "coupon"),
                    bd(parts, idx, "tip"),
                    bd(parts, idx, "commission_rate"),
                    bd(parts, idx, "commission_gst_rate")
            );

            PricingCalculator.Result result = calculator.calculate(input);
            List<String> diffs = new ArrayList<>();

            compare(diffs, "grand_total", result.grandTotal(), bd(parts, idx, "grand_total"));
            compare(diffs, "vendor_discount", result.vendorDiscount(), bd(parts, idx, "vendor_discount"));
            compare(diffs, "tax", result.tax(), bd(parts, idx, "tax"));
            compare(diffs, "delivery_fee", result.deliveryFee(), bd(parts, idx, "delivery_fee"));
            compare(diffs, "coupon_discount", result.couponDiscount(), bd(parts, idx, "coupon_discount"));
            compare(diffs, "commission", result.commission(), bd(parts, idx, "commission"));
            compare(diffs, "commission_gst", result.commissionGst(), bd(parts, idx, "commission_gst"));
            compare(diffs, "net_payout", result.netPayout(), bd(parts, idx, "net_payout"));

            if (diffs.isEmpty()) {
                pass++;
                System.out.println("  PASS  " + id);
            } else {
                fail++;
                System.out.println("  FAIL  " + id + " — " + String.join(", ", diffs));
            }
        }

        System.out.println();
        if (fail > 0) {
            System.out.println("PRICING PARITY FAIL (" + pass + " passed, " + fail + " failed)");
            System.exit(1);
        }
        System.out.println("PRICING PARITY PASS (" + pass + " vectors)");
    }

    private static void compare(List<String> diffs, String field, BigDecimal actual, BigDecimal expected) {
        if (actual.compareTo(expected) != 0) {
            diffs.add(field + " php=" + expected.toPlainString() + " java=" + actual.toPlainString());
        }
    }

    private static BigDecimal bd(String[] parts, Map<String, Integer> idx, String key) {
        Integer i = idx.get(key);
        if (i == null) {
            throw new IllegalStateException("missing column: " + key);
        }
        return new BigDecimal(parts[i].trim());
    }
}
